/* The toast: 361 wide inside the 393 frame, 8px padding, 24 in to the message. */
.toast {
  position: absolute;
  inset: 60px 16px auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  height: 56px;
  padding: 8px;
  border-radius: 32px;
  background: var(--bg-surface-translucent);
  backdrop-filter: blur(8px);
  box-shadow: 0 4px 20px 0 rgba(113, 117, 142, 0.25);
}

.toast__message { padding-left: 16px; font: var(--text-xs-semibold); }
.toast__dismiss { width: 40px; height: 40px; border-radius: 50%; background: rgb(255 255 255 / 0.4); }

