code.swiftui:
// Toast sits above the list, not over the tab bar.
struct MemoryToast: View {
  let message: String
  var onDismiss: () -> Void

  var body: some View {
    HStack(spacing: 8) {
      Text(message)
        .font(.system(size: 12, weight: .semibold))
        .padding(.leading, 16)
      Spacer(minLength: 0)
      Button(action: onDismiss) {
        Image(systemName: "xmark").frame(width: 40, height: 40)
      }
      .background(Circle().fill(.white.opacity(0.4)))
    }
    .padding(8)
    .frame(height: 56)
    .background(Capsule().fill(.thinMaterial))
    .padding(.horizontal, 16)
  }
}
